struct Document {                                    // loosely typed document
  std::unordered_map<std::string, std::any> props;
  template <class T> T get(const std::string& k) const {
    return std::any_cast<T>(props.at(k));            // throws on type mismatch
  }
  template <class T> void put(const std::string& k, T v) { props[k] = std::move(v); }
};
struct HasModel {                                    // typed view over a Document
  const Document& doc;
  std::string model() const { return doc.get<std::string>("model"); }
};
